function readBlocks(){return [...document.querySelectorAll('.block-select')].filter(el=>el.value).map(el=>({attackerId:el.dataset.attacker,blockerId:el.value}));}
async function copy(text){try{await navigator.clipboard.writeText(text);toast('Copiado.');}catch{modal('Copia este texto',`<textarea readonly>${esc(text)}</textarea>`);}}
// ——— Arrastrar cartas propias a sus zonas (ratón: arrastrar; táctil: mantener pulsado y arrastrar) ———
const ZONE_ES={battlefield:'Campo',hand:'Mano',graveyard:'Cementerio',exile:'Exilio',command:'Mando',library:'Biblioteca'};
let drag=null,suppressClickUntil=0,pendingResolve=null;
function beginDrag(){const d=drag;d.active=true;navigator.vibrate?.(12);d.el.classList.add('drag-source');document.body.classList.add('is-dragging');const img=d.el.querySelector('img');const g=document.createElement('div');g.className='drag-ghost';g.innerHTML=img?`<img src="${img.src}" alt="">`:`<span>${esc(d.el.getAttribute('aria-label')||'Carta')}</span>`;document.body.append(g);d.ghost=g;const bar=document.createElement('div');bar.className='drop-bar';bar.innerHTML=['battlefield','hand','graveyard','exile','command','library'].filter(z=>z!==d.zone).map(z=>`<div class="drop-chip" data-drop="${z}">${ZONE_ES[z]}</div>`).join('');document.body.append(bar);d.bar=bar;moveDrag(d.lx,d.ly);tickScroll();}
function dropTargetAt(x,y){return document.elementFromPoint(x,y)?.closest('[data-drop]')||null;}
function moveDrag(x,y){const d=drag;d.lx=x;d.ly=y;if(!d.active)return;d.ghost.style.transform=`translate(${x-36}px,${y-50}px) rotate(-4deg)`;const t=dropTargetAt(x,y);if(t!==d.over){d.over?.classList.remove('drop-over');t?.classList.add('drop-over');d.over=t;}}
function tickScroll(){if(!drag?.active)return;const y=drag.ly,h=innerHeight;const v=y<130&&y>70?-14:y>h-170?14:0;if(v)scrollBy(0,v);requestAnimationFrame(tickScroll);}
function endDrag(drop){const d=drag;drag=null;d.el.classList.remove('drag-source');document.body.classList.remove('is-dragging');d.ghost?.remove();d.bar?.remove();d.over?.classList.remove('drop-over');suppressClickUntil=Date.now()+400;const to=drop&&drop.dataset.drop;if(to&&to!==d.zone)Promise.resolve(dropCard(d.zone,d.iid,to)).catch(err=>toast(err.message));}
async function dropCard(from,iid,to){const p=game.players.find(q=>q.id===actor),c=p[from].find(x=>x.iid===iid);if(!c)return;
 if(to==='battlefield'&&['hand','command'].includes(from)){
  if(MC.isLand(c)){if(!act('CAST',{iid,from}))toast('Si un efecto te deja jugar otra tierra, usa Mover en la carta.');return;}
  {const x=MFX.additionalCost(c);if(x&&(x.sacrifice||x.discard)){cardDetail(c,from,actor);toast('Elige el coste adicional y lánzala desde aquí.');return;}if(/\{X\}/.test(c.mana_cost||'')){cardDetail(c,from,actor);toast('Elige el valor de X y lánzala desde aquí.');return;}}
  const plan=MC.autoPaymentPlan(game,actor,iid,from);let ok;
  if(plan.ok)ok=act('CAST',{iid,from,autoPay:true,autoPayRevision:game.revision,landIds:plan.landIds});
  else{let reserve=false;try{reserve=MC.autoPaymentPlan({...game,players:game.players.map(q=>q.id===actor?{...q,battlefield:[]}:q)},actor,iid,from).ok;}catch{}ok=act('CAST',{iid,from,payMana:reserve});if(ok&&!reserve)toast('Lanzada con pago manual: descuenta el maná a mano si hace falta.');}
  if(ok)startAutoResolve();return;}
 act('MOVE',{iid,from,to:to,position:'top'});}
// Tras soltar un hechizo en el campo, se resuelve solo si eres el jugador activo y no hay ronda de respuestas.
function resolver(){const top=game?.stack.at(-1);return top&&canControl(top.controllerId)?top.controllerId:game.activePlayerId;}
function startAutoResolve(){pendingResolve=true;setTimeout(autoResolve,0);}
// Resuelve en cadena lo que pusiste en la pila (hechizo y sus disparos) mientras eres el jugador activo y no hay ronda de respuestas.
// Se detiene si hace falta elegir objetivos, si es un disparo opcional o si el objeto es de otro jugador.
function autoResolve(){if(!pendingResolve||!game)return;const top=game.stack.at(-1);const r=MC.responseStatus(game);if(!top||$('#modal').open||top.controllerId!==actor||game.activePlayerId!==actor||r.enabled||top.optional||game.prompts?.length){if(top&&top.controllerId!==actor)toast('En la pila: resuélvela cuando la mesa lo acuerde.');pendingResolve=null;return;}const before=game.revision;handle({dataset:{action:'resolve'},disabled:false});if(game.revision!==before)setTimeout(autoResolve,0);else pendingResolve=null;}
document.addEventListener('pointerdown',e=>{const el=e.target.closest('.playcard[data-drag="1"]');if(!el||e.button>0||$('#modal').open||!game)return;drag={el,zone:el.dataset.zone,iid:(game.players.find(q=>q.id===actor)?.[el.dataset.zone]||[])[+el.dataset.index]?.iid,x:e.clientX,y:e.clientY,lx:e.clientX,ly:e.clientY,pid:e.pointerId,touch:e.pointerType!=='mouse',active:false};if(!drag.iid){drag=null;return;}if(drag.touch)drag.timer=setTimeout(()=>{if(drag&&!drag.active)beginDrag();},280);});
document.addEventListener('pointermove',e=>{if(!drag||e.pointerId!==drag.pid)return;const far=Math.hypot(e.clientX-drag.x,e.clientY-drag.y);if(!drag.active){if(drag.touch){if(far>10){clearTimeout(drag.timer);drag=null;}return;}if(far<8)return;drag.lx=e.clientX;drag.ly=e.clientY;beginDrag();}moveDrag(e.clientX,e.clientY);});
document.addEventListener('pointerup',e=>{if(!drag||e.pointerId!==drag.pid)return;clearTimeout(drag.timer);if(drag.active)endDrag(dropTargetAt(e.clientX,e.clientY));else drag=null;});
document.addEventListener('pointercancel',()=>{if(!drag)return;clearTimeout(drag.timer);if(drag.active)endDrag(null);else drag=null;});
