document.addEventListener('change',async e=>{if(e.target.id==='token-kind')tokenKindChange();if(e.target.id==='actor-select'){actor=e.target.value;render();}if(e.target.id==='json-file'){try{const file=e.target.files[0];if(!file)return;if(file.size>15000000)throw Error('El respaldo supera 15 MB.');const value=JSON.parse(await file.text());const decks=value.version===1?value.decks:[value];if(!Array.isArray(decks)||decks.length>100)throw Error('Formato de respaldo no válido.');for(const d of decks){if(!d||!Array.isArray(d.cards)||d.cards.length>250||typeof d.name!=='string'||d.cards.some(c=>!c||typeof c.name!=='string'))throw Error('El archivo contiene decks no válidos.');}const imported=decks.map(d=>({...d,id:MD.uid()}));let hist=[],leagues=[],saved=null;
if(value.version===1){
 if(!Array.isArray(value.history)||value.history.length>10000||!Array.isArray(value.tournaments)||value.tournaments.length>100)throw Error('Historial o ligas no válidos.');
 hist=value.history.filter(x=>x&&typeof x.id==='string'&&Array.isArray(x.players)&&x.players.every(p=>p&&typeof p.name==='string')&&Number.isFinite(x.turn)&&typeof x.date==='string');
 leagues=value.tournaments.filter(x=>x&&typeof x.name==='string'&&Array.isArray(x.players)&&x.players.every(n=>typeof n==='string')&&Array.isArray(x.matches)&&x.matches.every(n=>x.players.includes(n)));
 if(value.saved){const g=value.saved;if(!g||!Array.isArray(g.players)||g.players.length<1||g.players.length>8||!Array.isArray(g.log)||!Array.isArray(g.stack)||!Array.isArray(g.appliedActionIds)||!Number.isInteger(g.revision)||!Number.isFinite(g.seed)||!Number.isInteger(g.turn)||!Number.isInteger(g.phase)||g.players.some(p=>!p||typeof p.id!=='string'||typeof p.name!=='string'||!Number.isFinite(p.life)||!Number.isFinite(p.poison)||!p.commanderDamage||!p.mana||MC.COLORS.some(c=>!Number.isFinite(p.mana[c]))||MC.ZONES.some(z=>!Array.isArray(p[z])||p[z].length>500||p[z].some(c=>!c||typeof c.iid!=='string'||typeof c.name!=='string')))||!g.players.some(p=>p.id===g.activePlayerId))throw Error('La partida guardada no tiene una estructura válida.');saved=g;}
}
db.decks.push(...imported);for(const x of hist)if(!db.history.some(y=>y.id===x.id))db.history.push(x);for(const x of leagues)if(!db.tournaments.some(y=>y.id===x.id))db.tournaments.push(x);if(saved&&!game&&!online)db.saved=saved;save();close();editing=null;go('decks');toast(imported.length+' decks importados'+(saved?' y partida recuperable.':'.'));
}catch(err){toast(err.message);}}});
